  "The offline sale requires review.": "ការលក់ក្រៅបណ្ដាញនេះត្រូវការការពិនិត្យ។",
  "Offline checkout is active on this device.": "ការលក់ក្រៅបណ្ដាញកំពុងដំណើរការលើឧបករណ៍នេះ។",
  "Offline sales need review before they can post.": "ការលក់ក្រៅបណ្ដាញត្រូវការពិនិត្យមុនពេលបញ្ចូលទៅប្រព័ន្ធ។",
  "Synchronizing offline sales…": "កំពុងធ្វើសមកាលកម្មការលក់ក្រៅបណ្ដាញ…",
  "Downloads a trusted product, customer, stock and receipt snapshot for the current branch.": "ទាញយកទិន្នន័យផលិតផល អតិថិជន ស្តុក និងបង្កាន់ដៃដែលបានទុកចិត្តសម្រាប់សាខាបច្ចុប្បន្ន។",
  "A pending receipt is not a final server invoice until synchronization succeeds.": "បង្កាន់ដៃរង់ចាំមិនមែនជាវិក្កយបត្រចុងក្រោយទេ រហូតដល់ការធ្វើសមកាលកម្មបានជោគជ័យ។",
