  "Cancelling closes this pending transfer. No stock has moved yet, so inventory stays unchanged.": "ការលុបចោលនឹងបិទការផ្ទេររង់ចាំនេះ។ មិនទាន់មានការផ្លាស់ប្តូរស្តុកនៅឡើយទេ ដូច្នេះចំនួនស្តុកនៅដដែល។",
  "Cancelling restores all in-transit quantities to the source branch.": "ការលុបចោលនឹងបង្វែរចំនួនទំនិញកំពុងដឹកជញ្ជូនទាំងអស់ត្រឡប់ទៅសាខាដើមវិញ។",
