  "Profit & Loss: purchases increase inventory and become cost of goods when products are sold. Therefore purchases are not subtracted again from net profit. Only categories marked “Affects Profit & Loss” are included as other income or operating expenses.": "ចំណេញ និងខាត៖ ការទិញចូលបង្កើនស្តុក ហើយក្លាយជាថ្លៃដើមទំនិញនៅពេលលក់ចេញ។ ដូច្នេះការទិញចូលមិនត្រូវបានដកចេញម្តងទៀតពីចំណេញសុទ្ធឡើយ។ មានតែប្រភេទដែលបានកំណត់ថា “ប៉ះពាល់ចំណេញ និងខាត” ប៉ុណ្ណោះដែលត្រូវបានរាប់បញ្ចូលជាចំណូលផ្សេងៗ ឬចំណាយប្រតិបត្តិការ។",
  "purchases increase inventory and become cost of goods when products are sold. Therefore purchases are not subtracted again from net profit. Only categories marked “Affects Profit & Loss” are included as other income or operating expenses.": "ការទិញចូលបង្កើនស្តុក ហើយក្លាយជាថ្លៃដើមទំនិញនៅពេលលក់ចេញ។ ដូច្នេះការទិញចូលមិនត្រូវបានដកចេញម្តងទៀតពីចំណេញសុទ្ធឡើយ។ មានតែប្រភេទដែលបានកំណត់ថា “ប៉ះពាល់ចំណេញ និងខាត” ប៉ុណ្ណោះដែលត្រូវបានរាប់បញ្ចូលជាចំណូលផ្សេងៗ ឬចំណាយប្រតិបត្តិការ។",
